写日志示例：
```c
void write_access_log(FILE *fp,
const char *ip,
const char *method,
const char *path,
int status,
size_t bytes) {
    char time_buf[64];
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s %s %s %s %d %zu\n",
            time_buf, ip, method, path, status, bytes);
    fflush(fp);
}
```
